@Test
public void testReplaceThrowsStringIndexOutOfBoundsException() {
    final StringSubstitutor sub = new StringSubstitutor();
    // replace(char[], int, int)
    final char[] emptyCharArray = {};
    // offset greater than array length
    assertThatExceptionOfType(StringIndexOutOfBoundsException.class).isThrownBy(() -> sub.replace(emptyCharArray, 0, 1));
    // source != null && (offset > source.length || offset < 0)
    assertThatExceptionOfType(StringIndexOutOfBoundsException.class).isThrownBy(() -> sub.replace(emptyCharArray, 1, 0));
    // replace(String, int, int)
    // offset greater than source length
    assertThatExceptionOfType(StringIndexOutOfBoundsException.class).isThrownBy(() -> sub.replace("", 1, 1));
    // source != null && offset >= 0 && offset <= source.length() && (length > -offset + source.length() || length < 0)
    assertThatExceptionOfType(StringIndexOutOfBoundsException.class).isThrownBy(() -> sub.replace("", 0, 1));
}

