@Test
public void testInitialsSurrogatePairs() {
    // Tests with space as default delimiter
    assertThat(WordUtils.initials("\uD800\uDF00\uD800\uDF01 \uD800\uDF02\uD800\uDF03")).isEqualTo("\uD800\uDF00\uD800\uDF02");
    assertThat(WordUtils.initials("\uD800\uDF00\uD800\uDF01 \uD800\uDF02\uD800\uDF03", null)).isEqualTo("\uD800\uDF00\uD800\uDF02");
    assertThat(WordUtils.initials("\uD800\uDF00 \uD800\uDF02 ", null)).isEqualTo("\uD800\uDF00\uD800\uDF02");
    // Tests with UTF-16 as delimiters
    assertThat(WordUtils.initials("\uD800\uDF00\uD800\uDF01.\uD800\uDF02\uD800\uDF03", new char[] { '.' })).isEqualTo("\uD800\uDF00\uD800\uDF02");
    assertThat(WordUtils.initials("\uD800\uDF00\uD800\uDF01A\uD800\uDF02\uD800\uDF03", new char[] { 'A' })).isEqualTo("\uD800\uDF00\uD800\uDF02");
    // Tests with UTF-32 as delimiters
    assertThat(WordUtils.initials("\uD800\uDF00\uD800\uDF01\uD800\uDF14\uD800\uDF02\uD800\uDF03", new char[] { '\uD800', '\uDF14' })).isEqualTo("\uD800\uDF00\uD800\uDF02");
    assertThat(WordUtils.initials("\uD800\uDF00\uD800\uDF01\uD800\uDF14\uD800\uDF18\uD800\uDF02\uD800\uDF03", new char[] { '\uD800', '\uDF14', '\uD800', '\uDF18' })).isEqualTo("\uD800\uDF00\uD800\uDF02");
}

